import Image from "next/image";

// The liquid-glass shell mark, pre-rendered to WebP so it stays sharp on every screen
// (Safari renders SVG blur filters at low resolution). Generated by scripts/build-brand.mjs (npm run brand).
export function Logo({
  size = 40,
  priority = false,
  alt = "",
  className,
  variant = "mark",
}: {
  variant?: "mark" | "tile";
  size?: number;
  priority?: boolean;
  alt?: string;
  className?: string;
}) {
  const src =
    variant === "tile" ? "/brand/pearl-glass-tile.webp" : size <= 72 ? "/brand/pearl-glass-sm.webp" : "/brand/pearl-glass.webp";
  return (
    <Image
      src={src}
      alt={alt}
      width={size}
      height={variant === "tile" ? size : Math.round((size * 1112) / 1210)}
      priority={priority}
      className={className}
      unoptimized
    />
  );
}
